function modal(title,body){const t=$('#modalTemplate').content.cloneNode(true),m=t.querySelector('.modal-backdrop');m.querySelector('h3').textContent=title;m.querySelector('.modal-body').innerHTML=body;m.querySelector('.modal-actions').innerHTML='<button class="btn close-modal">Cancel</button><button class="btn primary modal-save">Save</button>';m.querySelectorAll('.close-modal').forEach(b=>b.onclick=()=>m.remove());document.body.appendChild(m);return m}
function vals(m){const o={};m.querySelectorAll('[name]').forEach(x=>o[x.name]=x.type==='number'?+x.value:x.value);return o}
function editProcess(){const p=(data().subprocesses?.[selectedStream]||[]).find(x=>x.flowId===selectedFlowId);if(!p)return;const m=modal('Edit As-Is process',`<div class="form-grid"><label>ID<input name="id" value="${esc(p.id)}"></label><label>Status<select name="status">${['Draft As-Is','BPO Review','SME Validated','Approved As-Is'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="full">Process name<input name="name" value="${esc(p.name)}"></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(p,vals(m));mark('processes');m.remove();render()}}
function editNode(id){const f=flowFor(selectedFlowId),n=f?.nodes.find(x=>x.id===id);if(!n)return;const m=modal('Edit process step',`<div class="form-grid"><label class="full">Activity<input name="label" value="${esc(n.label)}"></label><label>System<input name="system" value="${esc(n.system||'')}"></label><label>Type<select name="type">${['activity','decision','milestone'].map(s=>`<option ${n.type===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(n,vals(m));f.systems=[...new Set(f.nodes.map(x=>x.system).filter(Boolean))].sort();markFlow(f);m.remove();render()}}
function editPerson(id,stream=selectedStream){const arr=state.framework.people||=[],x=arr.find(p=>p.id===id),p=x||{id:uid('P'),name:'',role:'SME',stream,capacityPct:25};const m=modal(x?'Edit person':'Add SME',`<div class="form-grid"><label class="full">Name<input name="name" value="${esc(p.name)}"></label><label>Role<select name="role"><option ${p.role==='BPO'?'selected':''}>BPO</option><option ${p.role==='SME'?'selected':''}>SME</option></select></label><label>Value stream<select name="stream">${allStreams().map(s=>`<option value="${s.id}" ${p.stream===s.id?'selected':''}>${s.id} · ${esc(s.name)}</option>`).join('')}</select></label><label>Project capacity %<input type="number" name="capacityPct" value="${p.capacityPct||0}"></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(p,vals(m));if(!x)arr.push(p);mark('framework');m.remove();render()}}
function editTask(id,stream=selectedStream){const arr=state.tasks.tasks||=[],x=arr.find(t=>t.id===id),t=x||{id:uid('T'),title:'',stream,process:'All',owner:'',status:'Not Started',priority:'Medium',start:today(),due:'',phase:'Current State',dependency:''};const m=modal(x?'Edit task':'Add task',`<div class="form-grid"><label class="full">Task<input name="title" value="${esc(t.title)}"></label><label>Stream<input name="stream" value="${esc(t.stream)}"></label><label>Owner<input name="owner" value="${esc(t.owner)}"></label><label>Priority<select name="priority">${['High','Medium','Low'].map(s=>`<option ${t.priority===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Status<select name="status">${['Not Started','In Progress','Waiting','Ready for Review','BPO Review','Approved','Closed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Start<input type="date" name="start" value="${esc(t.start||'')}"></label><label>Due<input type="date" name="due" value="${esc(t.due||'')}"></label><label class="full">Dependency<input name="dependency" value="${esc(t.dependency||'')}"></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(t,vals(m));if(!x)arr.push(t);mark('tasks');m.remove();render()}}
function editPain(id,kind='Pain point'){const key=kind==='Opportunity'?'opportunities':'painPoints',arr=state.registers[key]||[],x=arr.find(z=>z.id===id),p=x||{id:uid(kind==='Opportunity'?'OPP':'PP'),stream:selectedStream,subprocess:'',title:'',impact:'To assess',phase:'To assess',status:'Open'};const m=modal(x?'Edit item':'Add issue / opportunity',`<div class="form-grid"><label>Type<select name="kind"><option ${kind==='Pain point'?'selected':''}>Pain point</option><option ${kind==='Opportunity'?'selected':''}>Opportunity</option></select></label><label>Stream<input name="stream" value="${esc(p.stream)}"></label><label class="full">Legacy subprocess<input name="subprocess" value="${esc(p.subprocess)}"></label><label class="full">Description<textarea name="title" rows="4">${esc(p.title)}</textarea></label><label>Impact<input name="impact" value="${esc(p.impact)}"></label><label>Phasing<input name="phase" value="${esc(p.phase)}"></label><label>Status<input name="status" value="${esc(p.status)}"></label></div>`);m.querySelector('.modal-save').onclick=()=>{const v=vals(m),newKey=v.kind==='Opportunity'?'opportunities':'painPoints';delete v.kind;Object.assign(p,v);if(!x)(state.registers[newKey]||=[]).push(p);mark('registers');m.remove();render()}}
function editRequirement(id){const arr=state.registers.requirements||[],x=arr.find(r=>r.id===id),r=x||{id:uid('REQ'),stream:selectedStream,title:'',painPoint:'',fitGap:'TBD',owner:allStreams().find(s=>s.id===selectedStream)?.bpo||'',status:'Draft'};const m=modal(x?'Edit requirement':'Add requirement',`<div class="form-grid"><label class="full">Requirement<input name="title" value="${esc(r.title)}"></label><label>Pain point<select name="painPoint"><option value="">—</option>${(state.registers.painPoints||[]).filter(p=>p.stream===selectedStream).map(p=>`<option value="${p.id}" ${r.painPoint===p.id?'selected':''}>${p.id}</option>`).join('')}</select></label><label>Fit / Gap<select name="fitGap">${['TBD','Fit','Fit with configuration','Process change','Extension','Integration','Reporting / Analytics','Deferred'].map(s=>`<option ${r.fitGap===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Owner<input name="owner" value="${esc(r.owner)}"></label><label>Status<select name="status">${['Draft','In Review','Approved','Deferred'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(r,vals(m));if(!x)arr.push(r);mark('registers');m.remove();render()}}
function editDecision(id){const arr=state.registers.decisions||[],x=arr.find(d=>d.id===id),d=x||{id:uid('DEC'),title:'',stream:selectedStream,owner:'Business Owner',due:'',status:'Open'};const m=modal(x?'Edit decision':'Add decision',`<div class="form-grid"><label class="full">Decision<input name="title" value="${esc(d.title)}"></label><label>Stream<input name="stream" value="${esc(d.stream)}"></label><label>Owner<input name="owner" value="${esc(d.owner)}"></label><label>Due<input type="date" name="due" value="${esc(d.due||'')}"></label><label>Status<select name="status">${['Open','Recommended','Decided','Closed'].map(s=>`<option ${d.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(d,vals(m));if(!x)arr.push(d);mark('registers');m.remove();render()}}
function editMilestone(id){const arr=state.milestones.milestones||[],x=arr.find(d=>d.id===id),m0=x||{id:uid('M'),name:'',stream:'Program',start:today(),end:'',status:'Proposed'};const m=modal(x?'Edit milestone':'Add milestone',`<div class="form-grid"><label class="full">Milestone<input name="name" value="${esc(m0.name)}"></label><label>Start<input type="date" name="start" value="${esc(m0.start)}"></label><label>End<input type="date" name="end" value="${esc(m0.end)}"></label><label>Stream<input name="stream" value="${esc(m0.stream)}"></label><label>Status<input name="status" value="${esc(m0.status)}"></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(m0,vals(m));if(!x)arr.push(m0);mark('milestones');m.remove();render()}}
function bindFlowEditor(){const f=flowFor(selectedFlowId);if(!f)return;$$('.flow-node').forEach(el=>{el.onclick=e=>{e.stopPropagation();if(window._connectFrom){if(window._connectFrom!==el.dataset.node){f.edges.push({from:window._connectFrom,to:el.dataset.node});window._connectFrom=null;markFlow(f);render()}return}selectedNodeId=el.dataset.node;render()};el.ondblclick=e=>{e.stopPropagation();editNode(el.dataset.node)};let st=null;el.onpointerdown=e=>{if(e.button!==0)return;const n=f.nodes.find(x=>x.id===el.dataset.node);st={mx:e.clientX,my:e.clientY,x:n.x,y:n.y,n};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!st)return;st.n.x=Math.max(0,st.x+e.clientX-st.mx);st.n.y=Math.max(0,st.y+e.clientY-st.my);el.style.left=st.n.x+'px';el.style.top=st.n.y+'px'};el.onpointerup=()=>{if(st){st=null;markFlow(f);render()}}});
 $('#flowCanvas')?.addEventListener('click',()=>{selectedNodeId=null;render()});$('#addActivity')?.addEventListener('click',()=>{f.nodes.push({id:uid('N'),label:'New activity',system:'',type:'activity',x:100,y:100});selectedNodeId=f.nodes.at(-1).id;markFlow(f);render()});$('#addDecision')?.addEventListener('click',()=>{f.nodes.push({id:uid('N'),label:'Decision?',system:'',type:'decision',x:180,y:180});selectedNodeId=f.nodes.at(-1).id;markFlow(f);render()});$('#connectNode')?.addEventListener('click',()=>{if(selectedNodeId){window._connectFrom=selectedNodeId;setSync('click target node')}});$('#editNode')?.addEventListener('click',()=>editNode(selectedNodeId));$('#deleteNode')?.addEventListener('click',()=>{if(!selectedNodeId||!confirm('Delete selected step?'))return;f.nodes=f.nodes.filter(n=>n.id!==selectedNodeId);f.edges=f.edges.filter(e=>e.from!==selectedNodeId&&e.to!==selectedNodeId);selectedNodeId=null;markFlow(f);render()})}
function bindPage(){
 $$('[data-open-stream]').forEach(x=>x.onclick=()=>openStream(x.dataset.openStream));$$('[data-stream-tab]').forEach(x=>x.onclick=()=>{streamTab=x.dataset.streamTab;render()});$$('[data-open-flow]').forEach(x=>x.onclick=()=>{selectedFlowId=x.dataset.openFlow;streamTab='asis';asIsMode='text';render()});$$('[data-asis]').forEach(x=>x.onclick=()=>{asIsMode=x.dataset.asis;render()});if($('#flowSelect'))$('#flowSelect').onchange=e=>{selectedFlowId=e.target.value;selectedNodeId=null;render()};$('#editProcess')?.addEventListener('click',editProcess);$$('[data-edit-node]').forEach(x=>x.onclick=()=>editNode(x.dataset.editNode));if(asIsMode==='flow')bindFlowEditor();
 $$('[data-edit-person]').forEach(x=>x.onclick=()=>editPerson(x.dataset.editPerson));$('#addPerson')?.addEventListener('click',()=>editPerson(null,selectedStream));$('#addPersonGlobal')?.addEventListener('click',()=>editPerson(null,'O2C'));
 $$('[data-edit-task]').forEach(x=>x.onclick=e=>{if(!e.target.matches('select'))editTask(x.dataset.editTask)});$$('[data-task-status]').forEach(x=>x.onchange=e=>{const t=state.tasks.tasks.find(z=>z.id===x.dataset.taskStatus);if(t){t.status=e.target.value;mark('tasks');render()}});$('#addTask')?.addEventListener('click',()=>editTask(null,view==='streams'?selectedStream:'O2C'));
 $$('[data-edit-pain]').forEach(x=>x.onclick=()=>editPain(x.dataset.editPain,x.dataset.kind));$('#addPain')?.addEventListener('click',()=>editPain());$$('[data-edit-req]').forEach(x=>x.onclick=()=>editRequirement(x.dataset.editReq));$('#addReq')?.addEventListener('click',()=>editRequirement());$$('[data-edit-decision]').forEach(x=>x.onclick=()=>editDecision(x.dataset.editDecision));$('#addDecision')?.addEventListener('click',()=>editDecision());$$('[data-edit-milestone]').forEach(x=>x.onclick=()=>editMilestone(x.dataset.editMilestone));$('#addMilestone')?.addEventListener('click',()=>editMilestone());
 $('#saveGh')?.addEventListener('click',()=>{const c={repoOwner:$('#ghOwner').value.trim(),repoName:$('#ghRepo').value.trim(),branch:$('#ghBranch').value.trim(),autoSyncSeconds:+$('#ghSeconds').value||60,token:$('#ghToken').value.trim(),autoSync:$('#ghAuto').checked};saveGhCfg(c,$('#ghRemember').checked);setSync('settings saved');render()});$('#pullGh')?.addEventListener('click',()=>pullGithub());$('#pushGh')?.addEventListener('click',()=>pushGithub());
}
init().catch(e=>{$('#app').innerHTML=`<div class="card empty">${esc(e.message)}</div>`;setSync('load error')});
